// SOURCE_ONLY proposal: ROOT must review, activate this one flag and approve the new self SHA.
// No execution/import by the preparing reviewer. Read-only SQL; immutable B-model outputs.
import * as fs from 'node:fs';
import { createHash } from 'node:crypto';
import { createRequire } from 'node:module';
import { fileURLToPath } from 'node:url';
const SOURCE_ONLY=false;
const root='/Users/petter.gjores/.codex/worktrees/planning-year-runtime/skolplattform';
const main='/Users/petter.gjores/dev/skolplattform';
const report='work/pilot/results/phase5-43-context-final-first-20261008.json';
const reportSha='815031288ce3944921f0631ed4faf089e2e8c7b8baffb6a1d2d5042788dec027';
const source='099c90f8d7bfc6f11d92f39d97986cc034644f70',build='17924ff417899dd5863c394bb4496a5bf22865bd';
const specSha='b9c06bd8ff7c4ae6c546b68b50b53dc796a0abdf523a01c0eb0f2d177066d826';
const helper='/private/tmp/phase5-43-3012-transfer-verification-draft-20261007/completion-files.mjs';
const helperSha='c6df15707bdf2db22fc328ee298e1519969e107e1f84ecf0d0ebadc975236272';
const targetHelper=root+'/work/pilot/verify-target.mjs';
const targetSha='984729588773c910a3f016bf1e42a0f9503caa22a21c8b702621cec75a3b009f';
const hash=b=>createHash('sha256').update(b).digest('hex');
const check=(ok,code)=>{if(!ok)throw Error(code);};
const equal=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
function parseArgs(argv){
 const o={};const fields={'--approved-script-sha256':'self','--reserved-out':'reserved','--completion-out':'completion'};
 for(let i=0;i<argv.length;i++){const key=fields[argv[i]];check(key&&!Object.hasOwn(o,key)&&argv[i+1]&&!argv[i+1].startsWith('--'),'EXACT_ARGUMENTS');o[key]=argv[++i];}
 check(/^[a-f0-9]{64}$/u.test(o.self??'')&&o.reserved&&o.completion&&o.reserved!==o.completion,'EXPLICIT_ROOT_APPROVAL');
 for(const p of [o.reserved,o.completion])check(/^\/Users\/petter\.gjores\/dev\/skolplattform\/work\/pilot\/results\/phase5-43-final-context-audit-bridge-[a-zA-Z0-9_-]+\.json$/u.test(p),'NEW_BRIDGE_OUTPUT_ONLY');
 return o;
}
function raw(full,expected){const s=fs.lstatSync(full);check(s.isFile()&&!s.isSymbolicLink()&&s.nlink===1,'RAW_FILE_SCOPE');const bytes=fs.readFileSync(full);check(hash(bytes)===expected,'RAW_SOURCE_SHA');return {bytes,value:JSON.parse(bytes.toString())};}
function allCases(suites,out=[]){for(const s of suites){for(const p of s.specs??[])for(const t of p.tests??[])out.push({title:p.title,project:t.projectName,result:t.results?.[0]});allCases(s.suites??[],out);}return out;}
function cleanup(c){const a=c.result.attachments.filter(a=>a.name==='cleanup.json');check(a.length===1,'ONE_NORMAL_CLEANUP');return JSON.parse(Buffer.from(a[0].body,'base64').toString());}
async function run(o){
 const selfBytes=fs.readFileSync(fileURLToPath(import.meta.url));check(hash(selfBytes)===o.self,'APPROVED_ACTIVATED_SELF_SHA');
 check(hash(fs.readFileSync(helper))===helperSha&&hash(fs.readFileSync(targetHelper))===targetSha,'REVIEWED_HELPER_BYTES');
 const {writeJsonFd,validateOwnedFileIdentity,publishCompletion}=await import(helper);
 const sealed=raw(root+'/'+report,reportSha),d=sealed.value;
 check(d.stats.expected===16&&d.stats.unexpected===0&&d.stats.skipped===0&&d.stats.flaky===0&&equal(d.errors,[]),'ACTUAL_FINAL_C16_REQUIRED');
 const cases=allCases(d.suites);check(cases.length===16&&cases.every(c=>c.result.status==='passed'&&c.result.retry===0),'EXACT_ACTUAL_CASES');
 const c4=cleanup(cases.find(c=>c.title.startsWith('C04:')&&c.project==='planning-year-desktop'));
 const c5=cleanup(cases.find(c=>c.title.startsWith('C05:')&&c.project==='planning-year-desktop'));
 const c6=cleanup(cases.find(c=>c.title.startsWith('C06:')&&c.project==='planning-year-desktop'));
 const last=cleanup(cases.at(-1));
 check(c5.afterRetainedAudit.count===197613&&c5.afterRetainedAudit.sha256==='769b2cb46b72b3a7e7ab59f8dca4289519023ae02c0036db5eb5f0844e4bea58','C05_RAW_PREFIX');
 check(c6.originalAuditHash==='f4f8272c1ecdeeab3b6b55387bcd52237d3df7d52bb7c93e01a69aea6267bb01','C06_RAW_ORIGINAL');
 check(last.afterRetainedAudit.count===198168&&last.afterRetainedAudit.sha256==='fe3cd7b7369f9cc87622f4b6157dfc6b6ca5d107f116380c43aafee8680524fa','FINAL_RAW_TERMINAL');
 check(hash(fs.readFileSync(root+'/web/e2e/phase5-planning-year-context.spec.ts'))===specSha,'FINAL_C_SPEC_BYTES');
 check(JSON.parse(fs.readFileSync(root+'/web/dist-protected/build-mode.json')).revision===build,'EXACT_BUILD_MARKER');
 // The original C06 count is NOT in the raw attachment. Find its first exactly matching
 // SQL prefix hash in this closed raw-derived bound; never invent the count.
 const lower=c5.afterRetainedAudit.count+1,upper=c6.beforeRetainedAudit.count;
 check(Number.isSafeInteger(upper)&&upper>=lower&&upper-lower<100,'CLOSED_PREFIX_SEARCH_BOUND');
 const resultsParent=main+'/work/pilot/results';check(fs.realpathSync(resultsParent)===resultsParent,'CANONICAL_OUTPUT_PARENT');
 check(!fs.existsSync(o.reserved)&&!fs.existsSync(o.completion),'EXCLUSIVE_NEW_OUTPUTS');
 let reservedFd,reservedStat,db,databaseClosed=false,reservedClosed=false,readCompletionKnown=false,failure=null,proof=null;
 const reserved={kind:'phase5-final-context-audit-bridge-reserved-v1',status:'FAIL',complete:false,reserved:true,readOnly:true,sourceRevision:source,buildRevision:build,reportSha256:reportSha,scriptSha256:o.self,requiresSuccessfulCommandExit:true};
 try{
  reservedFd=fs.openSync(o.reserved,fs.constants.O_WRONLY|fs.constants.O_CREAT|fs.constants.O_EXCL|fs.constants.O_NOFOLLOW,0o600);reservedStat=fs.fstatSync(reservedFd);validateOwnedFileIdentity(reservedStat,fs.lstatSync(o.reserved),'OWN_RESERVED_SCOPE');writeJsonFd(fs,reservedFd,reserved);
  const {assertTarget}=await import(targetHelper);const target=await assertTarget('protected',{requireRunning:false,requireIdp:false});
  const require=createRequire(root+'/web/package.json');db=require('postgres')(target.dbUrl,{max:1,prepare:false,connect_timeout:10,onnotice:()=>{},application_name:'phase5-finalC-audit-bridge-read-only'});
  proof=await db.begin(async tx=>{
   await tx`set transaction isolation level repeatable read read only`;
   await tx`set local statement_timeout='60s'`;await tx`set local lock_timeout='5s'`;
   const prefix=async n=>{const [v]=await tx`with chosen as (select e.id from public.security_events e order by e.id limit ${n})
    select count(*)::integer count,encode(extensions.digest(coalesce(jsonb_agg(to_jsonb(e) order by e.id),'[]'::jsonb)::text,'sha256'),'hex') sha256
    from public.security_events e join chosen on chosen.id=e.id`;return v;};
   const before=await prefix(197613);check(equal(before,c5.afterRetainedAudit),'OLD_FULL_PREFIX_PRESERVED');
   const terminal=await prefix(198168);const [{n:total}]=await tx`select count(*)::integer n from public.security_events`;check(total===198168&&equal(terminal,last.afterRetainedAudit),'EXACT_ALL_CURRENT_TERMINAL');
   const matches=[];const started=Date.now();
   for(let n=lower;n<=upper;n++){check(Date.now()-started<180000,'BOUNDED_SEARCH_DEADLINE');const v=await prefix(n);if(v.sha256===c6.originalAuditHash){matches.push(v);break;}}
   check(matches.length===1,'NEXT_ORIGINAL_SQL_PREFIX_MATCH');const next=matches[0];
   const reference=await tx`with numbered as (select e.*,row_number() over(order by e.id) rn from public.security_events e)
    select distinct customer_id,actor_identity_id,membership_id,assignment_id,session_id from numbered
    where rn>${c4.afterRetainedAudit.count} and rn<=197613 and action in ('gym_timplan_read','gym_timplan_row_changed') and outcome='ok'
      and customer_id is not null and actor_identity_id is not null and membership_id is not null and assignment_id is not null and session_id is not null`;
   check(reference.length===1,'UNIQUE_C05_ACTUAL_PRINCIPAL_TUPLE');const actor=reference[0];
   const [scope]=await tx`select c.name='Syntetiskt programplansprov' and m.identity_id=${actor.actor_identity_id}::uuid
    and m.customer_id=c.id and a.customer_id=c.id and a.membership_id=m.id and a.function='rektor' as valid
    from public.customers c join public.memberships m on m.id=${actor.membership_id}::uuid
    join public.access_assignments a on a.id=${actor.assignment_id}::uuid where c.id=${actor.customer_id}::uuid`;
   check(scope?.valid===true,'C05_RETAINED_OWN_SCOPE');
   const events=await tx`with numbered as (select e.*,row_number() over(order by e.id) rn from public.security_events e)
    select source,action,outcome,object_type,customer_id=${actor.customer_id}::uuid as same_customer,
     actor_identity_id=${actor.actor_identity_id}::uuid and membership_id=${actor.membership_id}::uuid
      and assignment_id=${actor.assignment_id}::uuid and session_id=${actor.session_id}::uuid as same_actor_tuple
    from numbered where rn>197613 and rn<=${next.count} order by rn`;
   check(events.length===next.count-197613,'EXACT_GAP_EVENT_COUNT');
   const safe=events.map(v=>({source:['db','worker'].includes(v.source)?v.source:'OTHER',action:/^[a-z0-9_]{1,90}$/u.test(v.action)?v.action:'OTHER',outcome:['ok','deny','error'].includes(v.outcome)?v.outcome:'OTHER',objectType:v.object_type===null?null:/^[a-z0-9_]{1,90}$/u.test(v.object_type)?v.object_type:'OTHER',sameCustomer:v.same_customer===true,sameActorTuple:v.same_actor_tuple===true}));
   // Attribution is evidence, not an assumption. Unknown/foreign tuples fail.
   check(safe.every(v=>v.sameCustomer&&v.sameActorTuple&&v.source!=='OTHER'&&v.action!=='OTHER'&&v.outcome!=='OTHER'),'GAP_OWNED_ATTRIBUTION_UNPROVEN');
   const after=await prefix(198168);check(equal(after,terminal),'READ_ONLY_SNAPSHOT_UNCHANGED');
   return {before,nextOriginal:next,terminal,gapCount:safe.length,events:safe,c05ActualTupleUnique:true,c05RetainedScopeValid:true,numericIdOrdering:true,sqlJsonbWholeRowDigest:true};
  });readCompletionKnown=true;
 }catch(error){failure={code:/^[A-Z0-9_]{1,90}$/u.test(error?.message??'')?error.message:'READ_ONLY_BRIDGE_FAILED'};}
 finally{
  if(db){try{await db.end({timeout:3});databaseClosed=true;}catch{failure??={code:'DATABASE_CLOSE_UNKNOWN'};}}
  if(reservedFd!==undefined){try{validateOwnedFileIdentity(reservedStat,fs.fstatSync(reservedFd),'OWN_RESERVED_CHANGED');validateOwnedFileIdentity(reservedStat,fs.lstatSync(o.reserved),'OWN_RESERVED_CHANGED');fs.closeSync(reservedFd);reservedClosed=true;}catch{failure??={code:'RESERVED_CLOSE_UNKNOWN'};}}
 }
 const complete=!failure&&readCompletionKnown&&databaseClosed&&reservedClosed;
 const completion={kind:'phase5-final-context-audit-bridge-completion-v1',status:complete?'PASS':'FAIL',complete,readOnly:true,sourceRevision:source,buildRevision:build,specSha256:specSha,reportSha256:reportSha,scriptSha256:o.self,scriptSource:selfBytes.toString(),closureHelperSha256:helperSha,reservedEvidence:{path:o.reserved,sha256:hash(fs.readFileSync(o.reserved))},readCompletionKnown,databaseClosed,reservedClosed,requiresSuccessfulCommandExit:true,proof,failure};
 publishCompletion(fs,o.completion,completion);check(complete,'BRIDGE_NOT_COMPLETE');
 process.stdout.write(JSON.stringify({code:'READ_ONLY_AUDIT_BRIDGE_COMPLETE',requiresSuccessfulCommandExit:true})+'\n');
}
if(SOURCE_ONLY)throw Error('SOURCE_ONLY_NOT_ACTIVATED');
await run(parseArgs(process.argv.slice(2))).catch(()=>{process.stderr.write('READ_ONLY_AUDIT_BRIDGE_FAILED\n');process.exitCode=1;});
